            expected
        );
        assert_eq!(parallel.cpu_budgets().line_workers(), 16);
        assert_eq!(storage(&parallel), warmed);
        assert_eq!(parallel.retained_activation_bytes(), activation_bytes);
        assert_eq!(parallel.retained_workspace_bytes(), workspace_bytes);
    }
