#!/usr/bin/env python3
"""Package existing local evidence. Never builds or executes OCR/benchmarks.

Missing future artifacts are recorded explicitly by default. Use --require-final
and --qualification-directory after validation to reject an incomplete package.
"""
import argparse
import datetime
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import subprocess


OUT = Path(__file__).resolve().parent
ROOT = OUT.parents[1]
DESTINATION = ROOT / "docs/reports/macos-arm64-2026-10-17-medium-mixed-regression.json"
REPRESENTATIVES = ("imgs_1", "imgs_00018069", "imgs_00006737")
SCORE_KEYS = ("detection_score", "recognition_score", "classification_score")
TEST_RESULT = re.compile(r"test result: (ok|FAILED)\. (\d+) passed; (\d+) failed; (\d+) ignored;")


def sha(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def location(path):
    try:
        return str(path.resolve().relative_to(ROOT))
    except ValueError:
        return str(path.resolve())


def read_json(path):
    return json.loads(path.read_text()) if path.is_file() else None


def json_artifact(path):
    if not path.is_file():
        return None
    return {"path": location(path), "sha256": sha(path), "data": read_json(path)}


def git(*arguments):
    return subprocess.check_output(["git", *arguments], cwd=ROOT, text=True)


def median_summary(worker):
    samples = worker.get("samples_ms", [])
    cpu = worker.get("process_cpu", {}).get("samples_ms", [])
    return {
        "measured_calls": len(samples),
        "wall_samples_ms": samples,
        "wall_median_ms": statistics.median(samples) if samples else None,
        "wall_range_ms": [min(samples), max(samples)] if samples else None,
        "process_cpu_samples_ms": cpu,
        "process_cpu_median_ms": statistics.median(cpu) if cpu else None,
        "peak_resident_bytes": worker.get("peak_resident_bytes"),
        "retained_capacities": worker.get("diagnostics", {}),
    }


def compare_results(expected, actual):
    """Original saved-golden contract, plus separately reported exact equality."""
    differences = []
    maximum_score = dict.fromkeys(SCORE_KEYS, 0.0)
    maximum_coordinate = 0.0
    for key in ("id", "text", "detected_count", "detector_resized_width", "detector_resized_height"):
        if expected.get(key) != actual.get(key):
            differences.append(key)
    elines, alines = expected.get("lines", []), actual.get("lines", [])
    if len(elines) != len(alines):
        differences.append("lines.length")
    for index, (left, right) in enumerate(zip(elines, alines)):
        for key in ("text", "classification_label", "applied_rotation_degrees", "emitted_count",
                    "recognition_content_width", "recognition_tensor_width", "recognition_time_steps"):
            if left.get(key) != right.get(key):
                differences.append(f"line[{index}].{key}")
        for key in SCORE_KEYS:
            e, a = left[key], right[key]
            delta = abs(e - a)
            if math.isfinite(delta):
                maximum_score[key] = max(maximum_score[key], delta)
            if not math.isfinite(e) or not math.isfinite(a) or delta > 1e-4 + 1e-4 * abs(e):
                differences.append(f"line[{index}].{key}")
        ep, ap = left.get("points", []), right.get("points", [])
        if len(ep) != 4 or len(ap) != 4:
            differences.append(f"line[{index}].points.length")
        for point, (ec, ac) in enumerate(zip(ep, ap)):
            if len(ec) != 2 or len(ac) != 2:
                differences.append(f"line[{index}].points[{point}].length")
            for axis, (e, a) in enumerate(zip(ec, ac)):
                delta = abs(e - a)
                if math.isfinite(delta):
                    maximum_coordinate = max(maximum_coordinate, delta)
                if not math.isfinite(e) or not math.isfinite(a) or delta > 0.5:
                    differences.append(f"line[{index}].points[{point}][{axis}]")
    return {"passed": not differences, "differences": differences,
            "complete_results_exactly_equal": expected == actual,
            "max_score_deltas": maximum_score, "max_coordinate_delta": maximum_coordinate}


def control_summary(report):
    if not report:
        return None
    grouped = {}
    for record in report.get("records", []):
        grouped.setdefault(record["version"], []).append(record)
    result = {}
    for version, records in grouped.items():
        wall = [v for record in records for v in record["worker"]["samples_ms"]]
        cpu = [v for record in records for v in record["worker"]["process_cpu"]["samples_ms"]]
        result[version] = {
            "processes": len(records), "first_inferences": len(records), "warmups": len(records),
            "measured_calls": len(wall), "wall_samples_ms": wall,
            "wall_median_ms": statistics.median(wall), "wall_range_ms": [min(wall), max(wall)],
            "process_cpu_samples_ms": cpu, "process_cpu_median_ms": statistics.median(cpu),
            "new_process_execution_seconds": sum(r["process_seconds"] for r in records),
        }
    return result


def owner_summary(profile):
    raw = profile.get("profile", {})
    count = raw.get("recognition_owner_count", 0)
    owners = raw.get("recognition_owners", [])[:count]
    ordered = sorted(owners, key=lambda owner: owner["dispatch_end_offset_ns"], reverse=True)
    wall_fields = ("det_preprocess_ns", "det_inference_ns", "det_postprocess_ns", "crop_ns",
                   "classification_wall_ns", "recognition_wall_ns")
    return {
        "stage_wall_ms": {key: raw.get(key, 0) / 1e6 for key in wall_fields},
        "total_ms": raw.get("total_ns", 0) / 1e6,
        "stage_remainder_ns": raw.get("total_ns", 0) - sum(raw.get(key, 0) for key in wall_fields),
        "critical_owner_index": ordered[0]["owner_index"] if ordered else None,
        "last_two_owner_completion_gap_ns": (ordered[0]["dispatch_end_offset_ns"] -
                                              ordered[1]["dispatch_end_offset_ns"]) if len(ordered) > 1 else None,
        "owners": [{**owner, "thread_cpu_to_wall_ratio":
                    owner["thread_cpu_ns"] / owner["wall_ns"]
                    if owner.get("thread_cpu_ns") is not None and owner.get("wall_ns") else None}
                   for owner in owners],
    }


def comparison_summary(report):
    if not report:
        return None
    summaries = []
    for row in report.get("cases", []):
        versions = row.get("versions", row.get("measurements", row.get("results", row.get("workers", {}))))
        if not versions:
            versions = {key: value for key, value in row.items()
                        if isinstance(value, dict) and "samples_ms" in value}
        workers = {}
        for version, value in versions.items():
            worker = value.get("data", value.get("worker", value)) if isinstance(value, dict) else {}
            if "samples_ms" in worker:
                workers[version] = worker
        pairs = {}
        names = list(workers)
        for index, left in enumerate(names):
            for right in names[index + 1:]:
                a, b = workers[left], workers[right]
                am, bm = statistics.median(a["samples_ms"]), statistics.median(b["samples_ms"])
                pairs[f"{right}_versus_{left}"] = {
                    "reference_version": left, "compared_version": right,
                    "latency_change_percent": 100 * (bm / am - 1),
                    "positive_change_means": "slower compared version",
                    "sample_ranges_overlap": max(min(a["samples_ms"]), min(b["samples_ms"])) <=
                                             min(max(a["samples_ms"]), max(b["samples_ms"])),
                    "output_contract": compare_results(a["result"], b["result"]),
                }
        summaries.append({"model": row.get("model"), "fixture": row.get("fixture"),
                          "recorded_order": row.get("order"),
                          "versions": {name: median_summary(value) for name, value in workers.items()},
                          "pairwise_comparisons": pairs})
    return summaries


def collect_test_logs():
    logs = {}
    for path in sorted(OUT.glob("*.log")):
        if not any(word in path.stem for word in ("test", "focused", "unit", "check", "clippy", "fmt", "qualif", "validation")):
            continue
        text = path.read_text(errors="replace")
        suites = [{"status": match[0], "passed": int(match[1]), "failed": int(match[2]),
                   "ignored": int(match[3])} for match in TEST_RESULT.findall(text)]
        logs[path.name] = {
            "path": location(path), "sha256": sha(path), "suite_results": suites,
            "passed_test_count": sum(s["passed"] for s in suites),
            "failed_test_count": sum(s["failed"] for s in suites),
            "ignored_test_count": sum(s["ignored"] for s in suites),
            "all_reported_test_suites_passed": all(s["status"] == "ok" and not s["failed"] for s in suites)
                                                if suites else None,
            "inference_note": "Build/check exit status is not inferred from log text.",
            "text": text,
        }
    return logs


def collect_integrity():
    manifest_path = ROOT / "tests/baseline/manifest.json"
    manifest = read_json(manifest_path)
    model_root = ROOT.parent / "SimdPaddleOCR/models"
    assets = []
    for asset in manifest["assets"]:
        path = model_root / asset["file"]
        actual = sha(path) if path.is_file() else None
        expected = [asset[key] for key in ("sha256", "sha256_crlf") if asset.get(key)]
        assets.append({"file": asset["file"], "sha256": actual, "accepted_sha256": expected,
                       "matches_manifest": actual in expected})
    fixtures = []
    for fixture in manifest["fixtures"]:
        if fixture["id"] not in REPRESENTATIVES:
            continue
        path = ROOT / "tests/baseline" / fixture["file"]
        actual = sha(path) if path.is_file() else None
        fixtures.append({**fixture, "actual_source_sha256": actual,
                         "source_matches_manifest": actual == fixture["sha256"]})
    jobs = {}
    job_paths = set(OUT.rglob("*.job.json"))
    job_paths.update((ROOT / "target/pipeline-analysis-20261017-current").glob("*.job.json"))
    for path in sorted(job_paths):
        job = read_json(path)
        pixels = Path(job["pixels"])
        actual = sha(pixels) if pixels.is_file() else None
        jobs[location(path)] = {"sha256": sha(path), "job": job, "actual_pixel_sha256": actual,
                                "pixel_matches_job": actual == job.get("pixel_sha256"),
                                "pixel_byte_count": pixels.stat().st_size if pixels.is_file() else None}
    return {"manifest_sha256": sha(manifest_path), "settings": manifest["settings"],
            "models": manifest["models"], "model_assets": assets, "fixtures": fixtures,
            "jobs": jobs, "saved_golden_sha256": {
                model: sha(ROOT / f"tests/baseline/expected/{model}.json")
                for model in ("tiny", "small", "medium")}}


def collect_source():
    roots = ("src", "examples", "tools")
    names = git("ls-files", "--cached", "--others", "--exclude-standard", "--", *roots,
                "Cargo.toml", "Cargo.lock", "rust-toolchain.toml").splitlines()
    files = {ROOT / name for name in names if (ROOT / name).is_file()}
    hashes = {location(path): sha(path) for path in sorted(files)}
    changed = git("diff", "--name-only", "--diff-filter=ACMRT", "--", *roots,
                  "Cargo.toml", "Cargo.lock", "rust-toolchain.toml").splitlines()
    untracked = git("ls-files", "--others", "--exclude-standard", "--", *roots).splitlines()
    text = {name: (ROOT / name).read_text(errors="replace") for name in sorted(set(changed + untracked))
            if (ROOT / name).is_file()}
    return {"head": git("rev-parse", "HEAD").strip(), "worktree_status": git("status", "--short"),
            "source_and_harness_sha256": hashes,
            "source_manifest_sha256": hashlib.sha256(json.dumps(hashes, sort_keys=True).encode()).hexdigest(),
            "tracked_patch": git("diff", "--no-ext-diff", "--", *roots, "Cargo.toml", "Cargo.lock",
                                 "rust-toolchain.toml", "README.md"),
            "changed_source_text": text}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=DESTINATION)
    parser.add_argument("--qualification-directory", type=Path, action="append",
                        help="Repeat to include multiple qualification invocations; also reads qualification-directories.txt.")
    parser.add_argument("--require-final", action="store_true")
    args = parser.parse_args()
    missing = []
    control = json_artifact(OUT / "control-report.json")
    threeway = json_artifact(OUT / "threeway-report.json")
    for name, value in (("control-report.json", control), ("threeway-report.json", threeway)):
        if value is None:
            missing.append(name)
    if threeway is not None and len(threeway["data"].get("cases", [])) != 9:
        missing.append("threeway-report.json: nine completed cases required")
    profiles = {}
    for scope_path in sorted(OUT.glob("*-profile-scope.json")):
        scope = json_artifact(scope_path)
        tag = scope["data"].get("tag", scope_path.name.removesuffix("-profile-scope.json"))
        cases = {}
        for model in scope["data"].get("cases", ("tiny", "small", "medium")):
            path = OUT / f"{tag}-{model}-profile.json"
            artifact = json_artifact(path)
            if artifact is None:
                missing.append(path.name)
            else:
                cases[model] = {**artifact, "derived": owner_summary(artifact["data"])}
        profiles[tag] = {"scope": scope, "cases": cases}
    for required_tag in ("diag-v0", "candidate-v1"):
        if required_tag not in profiles:
            missing.append(f"{required_tag}-profile-scope.json")
    test_logs = collect_test_logs()
    if not any(log["suite_results"] for log in test_logs.values()):
        missing.append("test log containing test result summaries")
    qualification_directories = list(args.qualification_directory or [])
    for name in ("qualification-directory.txt", "qualification-directories.txt"):
        pointer = OUT / name
        if pointer.is_file():
            qualification_directories.extend(Path(line.strip()) for line in pointer.read_text().splitlines()
                                             if line.strip() and not line.lstrip().startswith("#"))
    qualification_runs = []
    seen_directories = set()
    for directory in qualification_directories:
        directory = (directory if directory.is_absolute() else ROOT / directory).resolve()
        if directory in seen_directories:
            continue
        seen_directories.add(directory)
        run = json_artifact(directory / "run.json")
        differences = json_artifact(directory / "differences.json")
        qualification_runs.append({"directory": location(directory), "run": run,
                                   "differences": differences})
        if run is None:
            missing.append(f"qualification run.json: {location(directory)}")
    if not qualification_runs:
        missing.append("qualification directory (argument or qualification-directories.txt)")
    qualification = qualification_runs[0] if qualification_runs else None
    qualification_metadata = [entry["run"]["data"] for entry in qualification_runs if entry["run"]]
    qualification_summary = {
        "invocations": len(qualification_runs),
        "recorded_selected_requests": sum(run.get("case_count", 0) for run in qualification_metadata),
        "recorded_completed_requests": sum(run.get("completed_cases", 0) for run in qualification_metadata),
        "all_selected_invocations_passed": all(run.get("status") == "passed" for run in qualification_metadata)
                                           if len(qualification_metadata) == len(qualification_runs) and qualification_runs else None,
        "full_coverage_invocation_recorded": any(run.get("coverage") == "full" and run.get("status") == "passed"
                                                 for run in qualification_metadata),
        "note": "Request totals sum recorded invocations; focused selections do not establish full-corpus qualification.",
    }
    binaries = {}
    frozen = {OUT.parent / "arm64-kernel-adoption-20261017" / name
              for name in ("baseline-benchmark", "tail-v2-benchmark")}
    frozen.update(path for path in OUT.iterdir() if path.is_file() and
                  path.name.endswith(("-benchmark", "-profile", "-qualify", "-worker")))
    for path in sorted(frozen):
        if path.is_file():
            binaries[location(path)] = {"sha256": sha(path), "bytes": path.stat().st_size}
    version_paths = {
        "A": OUT.parent / "arm64-kernel-adoption-20261017/baseline-benchmark",
        "B": OUT.parent / "arm64-kernel-adoption-20261017/tail-v2-benchmark",
        "C": OUT / "candidate-v1-benchmark",
    }
    recorded_binary_hashes = threeway["data"].get("scope", {}).get("executable_sha256", {}) if threeway else {}
    version_executables = {}
    for version, path in version_paths.items():
        actual = binaries.get(location(path), {}).get("sha256")
        expected = recorded_binary_hashes.get(version)
        version_executables[version] = {"path": location(path), "actual_sha256": actual,
                                        "recorded_threeway_sha256": expected,
                                        "matches_recorded_threeway": actual == expected if expected is not None else None}
    historical_path = ROOT / "docs/reports/macos-arm64-2026-10-17-narrow-convolution-optimization.json"
    historical = read_json(historical_path)
    historical_context = None
    if historical:
        historical_context = {"path": location(historical_path), "sha256": sha(historical_path),
                              "baseline_provenance": historical.get("baseline_provenance"),
                              "prior_performance_ledger_seconds": historical.get("performance_ledger_seconds"),
                              "original_medium_mixed_comparison": next((row for row in historical["retained_comparison"]["cases"]
                                  if row["model"] == "medium" and row["fixture"] == "imgs_00006737"), None)}
    optional_json = {path.name: json_artifact(path) for path in sorted(OUT.glob("*.json"))
                     if path.name not in ("control-report.json", "threeway-report.json")
                     and not path.name.endswith("-profile.json")
                     and not path.name.startswith("control-")
                     and not path.name.endswith("-profile-scope.json")}
    report = {
        "schema_version": 1,
        "scope": "physical Apple M4 Medium mixed regression diagnosis and bounded three-version OCR comparison",
        "measurement_date": "2026-10-17 Asia/Shanghai",
        "packaged_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "package_completeness": {"status": "partial" if missing else "complete", "missing_inputs": missing,
                                 "note": "Package completeness does not assert performance or correctness success."},
        "version_roles": {"A": "original before narrow-convolution dispatch",
                          "B": "retained narrow-convolution dispatch",
                          "C": "candidate fix; see measured executable/source fingerprints"},
        "historical_context": historical_context,
        "same_executable_control": control,
        "control_summary": control_summary(control["data"]) if control else None,
        "diagnostic_profiles": profiles,
        "threeway_comparison": threeway,
        "threeway_summary": comparison_summary(threeway["data"]) if threeway else None,
        "validation": {"test_logs": test_logs, "qualification": qualification,
                       "qualification_runs": qualification_runs, "qualification_summary": qualification_summary},
        "source_provenance": collect_source(), "frozen_executables": binaries,
        "measured_version_executables": version_executables,
        "input_integrity": collect_integrity(),
        "supporting_artifacts": optional_json,
        "reproduction_scripts": {path.name: {"sha256": sha(path), "text": path.read_text()}
                                 for path in sorted(OUT.glob("*.py"))},
        "limitations": [
            "One physical M4 with unpinned macOS scheduling; logical Rayon worker indices are not P/E core IDs.",
            "Parallel stage work counters overlap wall phases; owner thread CPU excludes helper threads when nested kernels run.",
            "One instrumented profile per recorded case; separate execution from ordinary samples; do not rescale profiles to medians.",
            "Three fixed ordinary samples do not establish statistical significance or rule out host variation.",
            "Historical controls, diagnostic instrumentation and final comparisons are separate source/executable/configuration records.",
            "Acquisition, image decode, serialization and concurrent request throughput are outside ordinary predecoded-image latency.",
        ],
    }
    if args.require_final and missing:
        raise SystemExit("Incomplete evidence; refusing final package: " + "; ".join(missing))
    if args.require_final:
        assert len(threeway["data"].get("cases", [])) == 9, "final comparison must contain nine model/fixture cases"
        assert len(report["threeway_summary"]) == 9, "missing final comparison summaries"
        for row in report["threeway_summary"]:
            assert len(row["versions"]) == 3, "each final case needs three workers"
            assert all(v["measured_calls"] == 3 for v in row["versions"].values()), "exactly three samples required"
        assert qualification_summary["all_selected_invocations_passed"], "qualification did not pass"
        assert all(entry["matches_recorded_threeway"] for entry in version_executables.values()), "measured executable hash mismatch"
        assert all(not log["failed_test_count"] for log in test_logs.values()), "a recorded test log contains failures"
        assert all(asset["matches_manifest"] for asset in report["input_integrity"]["model_assets"]), "asset hash mismatch"
        assert all(job["pixel_matches_job"] for job in report["input_integrity"]["jobs"].values()), "pixel hash mismatch"
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, ensure_ascii=False, indent=2, allow_nan=False) + "\n")
    print(f"Wrote {location(args.output)} ({report['package_completeness']['status']}; {len(missing)} missing inputs)")


if __name__ == "__main__":
    main()
